import{af as a,z as t,J as o,ab as i}from"./chunks/framework.DOJTDj7A.js";const f=JSON.parse('{"title":"Preferences","description":"","frontmatter":{},"headers":[],"relativePath":"apps/cloud/account/preferences.md","filePath":"apps/cloud/account/preferences.md"}'),n={name:"apps/cloud/account/preferences.md"};function r(s,e,l,p,c,d){return t(),o("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1792763086000"},[...e[0]||(e[0]=[i('<h1 id="preferences" tabindex="-1">Preferences <a class="header-anchor" href="#preferences" aria-label="Permalink to &quot;Preferences&quot;">​</a></h1><p>Here you can control how things are displayed on your App and Portal.</p><figure><img src="https://upload.r2.lb.chasm.cloud/2025/10/imgur/bYsiZQs.png" alt="" tabindex="0"><figcaption></figcaption></figure><ul><li><p><strong>Use Imperial Units:</strong> Changes distance and speed units from kilometres to miles.</p></li><li><p><strong>Show Google Maps Button:</strong> Allows you to to open the coordinates of a tracker on google maps for street view and navigation.</p></li><li><p><strong>Hide Wi-Fi Locations:</strong> Hide the Wi-Fi-based locations that the tracker has collected. Please note this option is only available for certain trackers. This option will not stop the tracker from sending these locations, it will only stop displaying them.</p></li><li><p><strong>Disable Trip Grouping:</strong> When left unchecked, the portal will group the movement of the trackers into trips with start and stops. Trip grouping only works for very frequent location updates.</p></li><li><p><strong>Disable Map Tilt:</strong> The Map will not tilt when playing back trips.</p></li><li><p><strong>Hide Device Names:</strong> This will hide the name of each device below the markers on <a href="/docs/branch/31d42f615ccbbe66611e36a9fbfe42b065e51be507b5dab276c3de717a9a0d26/apps/cloud/map/device-view">the Map</a>.</p></li><li><p><strong>Show last 24h exactly:</strong> When opening <a href="/docs/branch/31d42f615ccbbe66611e36a9fbfe42b065e51be507b5dab276c3de717a9a0d26/apps/cloud/map/device-view#time-range">a device on the Map</a>, the default date and time selection will be the last 24 hours.</p></li><li><p><strong>Show today only:</strong> When opening <a href="/docs/branch/31d42f615ccbbe66611e36a9fbfe42b065e51be507b5dab276c3de717a9a0d26/apps/cloud/map/device-view#time-range">a device on the Map</a>, the default date and time selection will be today’s data.</p></li></ul>',4)])])}const g=a(n,[["render",r]]);export{f as __pageData,g as default};
